// design/tokens.json (copy of the suite's SUITE_TOKENS.json) -> app/tokens.css.
// Runs before dev and build; the generated file is committed too, so a fresh clone works
// without it.
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const tokens = JSON.parse(readFileSync(join(root, "design/tokens.json"), "utf8"));

// app variable -> suite token. The app names predate the suite file and every
// component uses them, so they stay.
const VARS = {
  bg: "bg0",
  surface: "bg1",
  elevated: "bg2",
  border: "stroke",
  text: "fg0",
  "text-muted": "fg1",
  "text-subtle": "fg2",
  accent: "accent",
  "accent-solid": "accentSolid",
  "accent-text": "accentText",
  critical: "warnRedText",
  caution: "cautionAmber",
  advisory: "advisoryCyan",
  ok: "okGreen",
  sim: "simViolet",
};

// fills stay the bright dark-theme values in both themes, used at 12-16 % alpha
const FILLS = {
  "critical-fill": "warnRed",
  "caution-fill": "cautionAmber",
  "advisory-fill": "advisoryCyan",
  "ok-fill": "okGreen",
};

function rgb(hex) {
  const n = parseInt(hex.slice(1), 16);
  return `${(n >> 16) & 255} ${(n >> 8) & 255} ${n & 255}`;
}

function block(selector, scheme, theme, extra = []) {
  const lines = [`${selector} {`, `  color-scheme: ${scheme};`, ""];
  for (const [name, key] of Object.entries(VARS)) {
    const hex = theme[key];
    if (!hex) throw new Error(`tokens.json: ${key} missing`);
    lines.push(`  --${name}: ${hex.toLowerCase()};`, `  --${name}-rgb: ${rgb(hex)};`);
  }
  return [...lines, ...extra, "}"].join("\n");
}

const dark = tokens.themes.dark;
const rootExtra = [
  "",
  ...Object.entries(FILLS).flatMap(([name, key]) => [
    `  --${name}: ${dark[key].toLowerCase()};`,
    `  --${name}-rgb: ${rgb(dark[key])};`,
  ]),
  "",
  ...tokens.chart.map((hex, i) => `  --series-${i + 1}: ${hex.toLowerCase()};`),
  "",
  `  --radius: ${tokens.radius.web}px;`,
];

const css = [
  `/* generated by scripts/tokens-to-css.mjs from design/tokens.json (${tokens.name} ${tokens.version}); edit the json, not this file */`,
  "",
  block(":root", "dark", dark, rootExtra),
  "",
  block(".light", "light", tokens.themes.light),
  "",
].join("\n");

writeFileSync(join(root, "app/tokens.css"), css);
console.log("app/tokens.css written");
